     "summary": "智东西 作者 | 毕伟豪 编辑｜漠影 当下，AI正在从能力展示走向真实应用。今年WAIC 2026上亮相了众多AI成果，但诸多机器人、大模型相关的前沿科技，离普通人的日常生活还是有些距离。 在腾讯集团展台的一众硬科技中，和平精英是为数不多亮相的游戏产品。作为一款在春节期间日活超9000万的射击游戏，它在WAIC上的露面，并不是靠“热度和流水”，而是作为普通人感受前沿AI成果的重要入口，登上展台。 但AI进入游戏，提供功能入口仅仅是开始，真正的难点在于，AI能否融入玩家的游戏体",
